EMPTY = Leaf(b'')


def geo_sum(ratio, count):
    """``sum(ratio**j for j in range(count))`` modulo ``2**64``."""
    result_power = 1
    result_sum = 0
    block_power = ratio
    block_sum = 1
    while count:
        if count & 1:
            result_sum = (result_sum + result_power * block_sum) & _MASK
            result_power = (result_power * block_power) & _MASK
        block_sum = (block_sum + block_power * block_sum) & _MASK
        block_power = (block_power * block_power) & _MASK
        count >>= 1
    return result_sum


def leaf(data):
    """A literal byte run."""
    if not data:
        return EMPTY
    return Leaf(data)


def literal(data):
    """Compatibility helper: literal bytes."""
    return leaf(data)


def size(node):
    """Logical length of a rope."""
    return node.length if node is not None else 0


def concat(left, right):
    """Concatenate two ropes, keeping the result weight balanced."""
    return merge(left, right)


def merge(left, right):
    """Weight balanced concatenation of two ropes."""
    if left is None or left.weight == 0:
        return right
    if right is None or right.weight == 0:
        return left
    if left.weight >= right.weight:
        if left.kind == Cat.kind:
            return balance(left.left, merge(left.right, right))
        return Cat(left, right)
    if right.kind == Cat.kind:
        return balance(merge(left, right.left), right.right)
    return Cat(left, right)


def balance(left, right):
    """Restore the weight balance invariant of a concatenation."""
    if left is None or left.weight == 0:
        return right
    if right is None or right.weight == 0:
        return left
    if left.weight > 3 * right.weight:
        return Cat(left.left, balance(left.right, right))
    if right.weight > 3 * left.weight:
        return Cat(balance(left, right.left), right.right)
    return Cat(left, right)


def repeat(node, count):
    """Repeat a rope ``count`` times."""
    if node is None or count <= 0 or node.length == 0:
        return EMPTY
    if count == 1:
        return node
    if node.kind == Rep.kind:
        return Rep(node.child, node.count * count)
    return Rep(node, count)


def cut(node, start, end):
    """Return the byte range ``[start:end)`` of a rope."""
    if node is None:
        return EMPTY
    if start < 0 or end < start or end > node.length:
        raise ValueError('slice range')
    if start == end:
        return EMPTY
    if start == 0 and end == node.length:
        return node
    if node.length == 0:
        return EMPTY
    if node.kind == Leaf.kind:
        return Leaf(node.data[start:end])
    if node.kind == Rep.kind:
        unit = node.child.length
        first = start // unit
        last = (end - 1) // unit
        if first == last:
            offset = start - first * unit
            return cut(node.child, offset, offset + (end - start))
        parts = []
        head = start - first * unit
        parts.append(cut(node.child, head, unit))
        middle = last - first - 1
        if middle > 0:
            parts.append(repeat(node.child, middle))
        tail = end - last * unit
        if tail:
            parts.append(cut(node.child, 0, tail))
        result = parts[0]
        for part in parts[1:]:
            result = merge(result, part)
        return result
    left = node.left.length
    if end <= left:
        return cut(node.left, start, end)
    if start >= left:
        return cut(node.right, start - left, end - left)
    return merge(cut(node.left, start, left), cut(node.right, 0, end - left))


def materialize(node, limit=65536):
    """Expand a bounded rope into bytes."""
    if node is None:
        return b''
    if node.length > limit:
        raise ValueError('bounded materialization')
    out = bytearray()
    _fill(node, out)
    return bytes(out)


